+      --surface: #ffffff;
+      --surface-muted: #eef4ff;
+      --text: #172033;
+      --muted: #51607a;
+      --border: #c9d4e5;
+      --accent: #2556d8;
+      --accent-strong: #1c44ac;
+      --success-bg: #eaf7ef;
+      --success-text: #17633f;
+      --shadow: 0 24px 60px rgba(23, 32, 51, 0.12);
+      --radius: 24px;
+    }
+
+    * {
+      box-sizing: border-box;
+    }
+
+    body {
+      margin: 0;
+      min-height: 100vh;
+      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
+      background:
+        radial-gradient(circle at top, #dfe8ff 0, transparent 40%),
+        linear-gradient(180deg, #f8faff 0%, var(--bg) 100%);
+      color: var(--text);
+    }
+
+    .skip-link {
+      position: absolute;
+      left: 1rem;
+      top: 1rem;
+      transform: translateY(-200%);
+      background: var(--text);
+      color: #fff;
+      padding: 0.75rem 1rem;
+      border-radius: 0.75rem;
+      text-decoration: none;
+      z-index: 10;
+    }
+
+    .skip-link:focus {
+      transform: translateY(0);
+      outline: 3px solid #8db1ff;
+      outline-offset: 2px;
+    }
+
+    main {
+      min-height: 100vh;
+      display: grid;
+      place-items: center;
+      padding: 1.5rem;
+    }
+
+    .card {
+      width: min(100%, 30rem);
+      background: var(--surface);
+      border: 1px solid rgba(201, 212, 229, 0.7);
+      border-radius: var(--radius);
+      box-shadow: var(--shadow);
+      padding: 2rem;
+    }
+
+    .eyebrow {
+      margin: 0 0 0.75rem;
+      color: var(--accent);
+      font-size: 0.875rem;
+      font-weight: 700;
+      letter-spacing: 0.04em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(1.75rem, 4vw, 2.25rem);
+      line-height: 1.1;
+    }
+
+    .intro {
+      margin: 0.85rem 0 1.5rem;
+      color: var(--muted);
+      line-height: 1.6;
+    }
+
+    form {
+      display: grid;
+      gap: 1rem;
+    }
+
+    .form-field {
+      padding: 1rem;
+      border: 1px solid var(--border);
+      border-radius: 1rem;
+      background: var(--surface-muted);
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: start;
+      gap: 0.875rem;
+    }
+
+    input[type="checkbox"] {
+      width: 1.15rem;
+      height: 1.15rem;
+      margin-top: 0.15rem;
+      accent-color: var(--accent);
+      flex: 0 0 auto;
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.5;
+    }
+
+    .helper-text {
+      margin: 0.5rem 0 0 2rem;
+      color: var(--muted);
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 999px;
+      padding: 0.95rem 1.25rem;
+      background: linear-gradient(135deg, var(--accent) 0%, #3e7bff 100%);
+      color: #fff;
+      font: inherit;
+      font-weight: 700;
+      cursor: pointer;
+      transition: transform 120ms ease, box-shadow 120ms ease, background 120ms ease;
+      box-shadow: 0 16px 30px rgba(37, 86, 216, 0.24);
+    }
+
+    button:hover {
+      transform: translateY(-1px);
+      background: linear-gradient(135deg, var(--accent-strong) 0%, #326df1 100%);
+    }
+
+    button:focus-visible,
+    input[type="checkbox"]:focus-visible {
+      outline: 3px solid #8db1ff;
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin: 0;
+      font-weight: 600;
+      color: var(--success-text);
+    }
+
+    .status[data-state="success"] {
+      padding: 0.875rem 1rem;
+      border-radius: 0.875rem;
+      background: var(--success-bg);
+    }
+
+    @media (max-width: 480px) {
+      .card {
+        padding: 1.5rem;
+      }
+
+      .helper-text {
+        margin-left: 0;
+      }
+    }
+
+    @media (forced-colors: active) {
+      .card,
+      .form-field {
+        border-color: ButtonText;
+      }
+
+      .card,
+      .form-field,
+      button {
+        background: Canvas;
+        color: CanvasText;
+        box-shadow: none;
+      }
+
+      button {
+        border: 1px solid ButtonText;
+      }
+
+      .status[data-state="success"] {
+        background: Canvas;
+        color: CanvasText;
+        border: 1px solid ButtonText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <main id="main-content">
+    <section class="card" aria-labelledby="page-title">
+      <p class="eyebrow">Account setup</p>
+      <h1 id="page-title">Confirm your agreement</h1>
+      <p class="intro">Review the final step below to continue with your product access request.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="terms-consent"
+              name="terms-consent"
+              type="checkbox"
+              required
+              aria-describedby="terms-help"
+            >
+            <label for="terms-consent">I agree to the Terms of Use</label>
+          </div>
+          <p class="helper-text" id="terms-help">Required to submit your request.</p>
+        </div>
+
+        <button type="submit">Submit</button>
+        <p class="status" id="form-status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('consent-form');
+    const checkbox = document.getElementById('terms-consent');
+    const status = document.getElementById('form-status');
+
+    function clearError() {
+      checkbox.setCustomValidity('');
+      checkbox.removeAttribute('aria-invalid');
+    }
+
+    checkbox.addEventListener('change', () => {
+      if (checkbox.checked) {
+        clearError();
+      }
+    });
+
+    checkbox.addEventListener('invalid', () => {
+      checkbox.setCustomValidity('Please agree to the Terms of Use before submitting.');
+      checkbox.setAttribute('aria-invalid', 'true');
+      status.textContent = '';
+      status.removeAttribute('data-state');
+    });
+
+    form.addEventListener('submit', (event) => {
+      clearError();
+
+      if (!form.checkValidity()) {
+        event.preventDefault();
+        checkbox.reportValidity();
+        checkbox.focus();
+        return;
+      }
+
+      event.preventDefault();
+      status.textContent = 'Consent recorded. You can proceed.';
+      status.setAttribute('data-state', 'success');
+      form.reset();
+    });
+  </script>
+</body>
+</html>
*** End Patch
